<template>
	<view class="container">
		<!-- 自定义导航栏 -->
		<view class="custom-navbar">
			<view class="navbar-content">
				<text class="navbar-title">陪诊接单大厅</text>
				<view class="navbar-right">
					<text class="filter-icon" @click="toggleFilter">🔍</text>
					<text class="refresh-icon" @click="refreshOrders">🔄</text>
				</view>
			</view>
		</view>
		
		<!-- 筛选面板 -->
		<view class="filter-panel" v-show="showFilter">
			<view class="filter-content">
				<view class="filter-row">
					<text class="filter-label">距离：</text>
					<view class="filter-options">
						<text 
							v-for="option in distanceOptions" 
							:key="option.value"
							:class="['filter-option', { active: filterData.distance === option.value }]"
							@click="setFilter('distance', option.value)"
						>
							{{ option.label }}
						</text>
					</view>
				</view>
				
				<view class="filter-row">
					<text class="filter-label">报酬：</text>
					<view class="filter-options">
						<text 
							v-for="option in priceOptions" 
							:key="option.value"
							:class="['filter-option', { active: filterData.price === option.value }]"
							@click="setFilter('price', option.value)"
						>
							{{ option.label }}
						</text>
					</view>
				</view>
				
				<view class="filter-row">
					<text class="filter-label">时间：</text>
					<view class="filter-options">
						<text 
							v-for="option in timeOptions" 
							:key="option.value"
							:class="['filter-option', { active: filterData.time === option.value }]"
							@click="setFilter('time', option.value)"
						>
							{{ option.label }}
						</text>
					</view>
				</view>
				
				<view class="filter-actions">
					<button class="filter-btn reset" @click="resetFilter">重置</button>
					<button class="filter-btn confirm" @click="applyFilter">确定</button>
				</view>
			</view>
		</view>
		
		<!-- 订单列表 -->
		<scroll-view 
			class="order-list" 
			:class="{ 'with-filter': showFilter }"
			scroll-y="true" 
			@scrolltolower="loadMore"
		>
			<OrderCard 
				v-for="(order, index) in orderList" 
				:key="order.id"
				:order-data="order"
				:show-actions="true"
				:action-type="'accept'"
				@contact="contactPatient"
				@main-action="acceptOrder"
				@click="viewOrderDetail(order)"
				@accept="acceptOrder(order)"
			/>
		</scroll-view>
		
		<!-- 加载更多提示 -->
		<view class="loading-more" v-if="isLoading">
			<text>加载中...</text>
		</view>
	</view>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import OrderCard from '@/components/OrderCard.vue'

// 响应式数据
const originalOrderList = ref([
	{
		id: 1,
		userName: '王大爷',
		userAge: 72,
		userGender: '男',
		userAvatar: '/static/user-placeholder.png',
		serviceType: '糖尿病复查',
		hospitalName: '北京协和医院',
		distance: '1.8km',
		appointmentTime: '2023-11-15 09:30',
		appointmentEndTime: '2023-11-15 11:30',
		duration: '2小时',
		serviceDetail: '代取化验报告',
		specialNote: '需要轮椅协助',
		price: 180,
		distanceValue: 1.8,
		timeValue: new Date('2023/11/15 09:30').getTime()
	},
	{
		id: 2,
		userName: '陈女士',
		userAge: 28,
		userGender: '女',
		userAvatar: '/static/user-placeholder.png',
		serviceType: '孕期检查',
		hospitalName: '上海妇产科医院',
		distance: '3.2km',
		appointmentTime: '2023-11-16 14:00',
		appointmentEndTime: '2023-11-16 16:30',
		duration: '2.5小时',
		serviceDetail: '陪同产检',
		specialNote: '怀孕6个月，行动不便',
		price: 220,
		distanceValue: 3.2,
		timeValue: new Date('2023/11/16 14:00').getTime()
	},

])

// 筛选相关数据
const showFilter = ref(false)
const filterData = ref({
	distance: '',
	price: '',
	time: ''
})

// 筛选选项
const distanceOptions = ref([
	{ label: '全部', value: '' },
	{ label: '1km内', value: '1' },
	{ label: '3km内', value: '3' },
	{ label: '5km内', value: '5' }
])

const priceOptions = ref([
	{ label: '全部', value: '' },
	{ label: '价格升序', value: 'asc' },
	{ label: '价格降序', value: 'desc' }
])

const timeOptions = ref([
	{ label: '全部', value: '' },
	{ label: '时间最近', value: 'nearest' },
	{ label: '时间最远', value: 'farthest' }
])

// 计算属性 - 筛选后的订单列表
const orderList = computed(() => {
	let filtered = [...originalOrderList.value]
	
	// 距离筛选
	if (filterData.value.distance) {
		const maxDistance = parseFloat(filterData.value.distance)
		filtered = filtered.filter(order => order.distanceValue <= maxDistance)
	}
	
	// 价格排序
	if (filterData.value.price === 'asc') {
		filtered.sort((a, b) => a.price - b.price)
	} else if (filterData.value.price === 'desc') {
		filtered.sort((a, b) => b.price - a.price)
	}
	
	// 时间排序
	if (filterData.value.time === 'nearest') {
		filtered.sort((a, b) => a.timeValue - b.timeValue)
	} else if (filterData.value.time === 'farthest') {
		filtered.sort((a, b) => b.timeValue - a.timeValue)
	}
	
	return filtered
})

const isLoading = ref(false)

// 自动刷新定时器
let autoRefreshTimer = null

// 开始自动刷新
const startAutoRefresh = () => {
	stopAutoRefresh() // 先清除之前的定时器
	autoRefreshTimer = setInterval(() => {
		loadOrders(true)
	}, 30000) // 每30秒自动刷新一次
}

// 停止自动刷新
const stopAutoRefresh = () => {
	if (autoRefreshTimer) {
		clearInterval(autoRefreshTimer)
		autoRefreshTimer = null
	}
}

// 页面生命周期
onMounted(() => {
	loadOrders()
	startAutoRefresh() // 开始自动刷新
})

// 页面卸载时清除定时器
onUnmounted(() => {
	stopAutoRefresh()
})

// 页面显示时恢复自动刷新
const onShow = () => {
	startAutoRefresh()
}

// 页面隐藏时停止自动刷新
const onHide = () => {
	stopAutoRefresh()
}

// 导出页面生命周期方法
defineExpose({
	onShow,
	onHide
})

// 方法定义
// 加载订单列表
const loadOrders = (isRefresh = false) => {
	// TODO: 调用后端API获取订单列表
	console.log('加载订单列表', isRefresh ? '(刷新模式)' : '')
	
	// 如果是刷新模式，重新加载数据
	if (isRefresh) {
		// 重置订单列表
		originalOrderList.value = [...originalOrderList.value]
	}
}

// 查看订单详情
const viewOrderDetail = (order) => {
	uni.navigateTo({
		url: `/subpkg/order/detail?orderId=${order.id}`
	})
}

// 刷新订单
const refreshOrders = () => {
	uni.showToast({
		title: '正在刷新订单...',
		icon: 'loading',
		duration: 1500
	})
	
	// 模拟刷新延迟
	setTimeout(() => {
		loadOrders(true) // 传入刷新模式参数
		uni.showToast({
			title: '刷新完成',
			icon: 'success',
			duration: 1000
		})
	}, 1500)
}

// 筛选相关方法
// 切换筛选面板
const toggleFilter = () => {
	showFilter.value = !showFilter.value
}

// 设置筛选条件
const setFilter = (type, value) => {
	filterData.value[type] = filterData.value[type] === value ? '' : value
}

// 重置筛选
const resetFilter = () => {
	filterData.value = {
		distance: '',
		price: '',
		time: ''
	}
}

// 应用筛选
const applyFilter = () => {
	showFilter.value = false
	uni.showToast({
		title: '筛选已应用',
		icon: 'success',
		duration: 1500
	})
}

// 加载更多
const loadMore = () => {
	if (isLoading.value) return
	isLoading.value = true
	// TODO: 加载更多订单
	setTimeout(() => {
		isLoading.value = false
	}, 1000)
}

// 联系患者
const contactPatient = (order) => {
	uni.showActionSheet({
		itemList: ['拨打电话', '发送消息'],
		success: (res) => {
			if (res.tapIndex === 0) {
				// 拨打电话
				uni.makePhoneCall({
					phoneNumber: order.phone
				})
			} else if (res.tapIndex === 1) {
				// 发送消息
				uni.navigateTo({
					url: `/subpkg/chat/chat?userId=${order.userId}&name=${order.userName}`
				})
			}
		}
	})
}

// 接单
const acceptOrder = (actionData) => {
	const order = actionData.data
	uni.showModal({
		title: '确认接单',
		content: `确定要接受${order.userName}的陪诊订单吗？`,
		success: (res) => {
			if (res.confirm) {
				// TODO: 调用接单API
				// 模拟API调用成功
				
				// 生成统一格式的时间字符串 (yyyy/MM/dd HH:mm)
				const now = new Date()
				const year = now.getFullYear()
				const month = String(now.getMonth() + 1).padStart(2, '0')
				const day = String(now.getDate()).padStart(2, '0')
				const hours = String(now.getHours()).padStart(2, '0')
				const minutes = String(now.getMinutes()).padStart(2, '0')
				const createTime = `${year}/${month}/${day} ${hours}:${minutes}`
				
				const acceptedOrder = {
					...order,
					status: 'accepted',
					acceptTime: new Date().toISOString(),
					orderNo: order.orderNo || `PZ${Date.now()}${Math.floor(Math.random() * 1000)}`,
					createTime: order.createTime || createTime
				}
				
				// 将订单添加到本地存储的已接单列表
				let acceptedOrders = uni.getStorageSync('acceptedOrders') || []
				acceptedOrders.push(acceptedOrder)
				uni.setStorageSync('acceptedOrders', acceptedOrders)
				
				// 通知订单页面更新
				uni.$emit('orderAccepted', acceptedOrder)
				
				uni.showToast({
					title: '接单成功',
					icon: 'success'
				})
				
				// 从原始订单列表中移除已接单的订单
				const index = originalOrderList.value.findIndex(item => item.id === order.id)
				if (index > -1) {
					originalOrderList.value.splice(index, 1)
				}
			}
		}
	})
}
</script>

